export interface EmitAngularClientOptions {
  endpointsImportPath?: string;
}

/**
 * Emits the generated Angular swagger client implementation.
 *
 * @param options The import path used to reference generated endpoint definitions.
 * @returns The TypeScript source for the Angular client file.
 */
export function emitAngularClient(options: EmitAngularClientOptions = {}): string {
  const endpointsImportPath = options.endpointsImportPath ?? "./api-endpoints";

  return String.raw`
/* eslint-disable */
// This file was generated by @let-aurn/swagger-client.
import { HttpClient, HttpContext, HttpHeaders, HttpParams } from '@angular/common/http';
import { EnvironmentProviders, Inject, Injectable, InjectionToken, makeEnvironmentProviders, Type } from '@angular/core';
import { Observable, defer, map } from 'rxjs';
import type {
  AnyApiEndpoint,
  BodyVariablesOf,
  HeaderVariablesOf,
  HttpMethod,
  PathVariablesOf,
  QueryVariablesOf,
  ResponseOf
} from '${endpointsImportPath}';

/**
 * Configures the generated Angular swagger client.
 */
export interface SwaggerClientConfig {
  baseUrl: string;
  httpClient?: Type<SwaggerHttpClient>;
}

/**
 * Describes an HTTP request produced by the generated swagger client.
 */
export interface SwaggerHttpRequest {
  method: HttpMethod;
  url: string;
  headers?: Record<string, string>;
  query?: Record<string, unknown>;
  body?: unknown;
  context?: HttpContext;
}

/** Header names are lowercase; values retain all repetitions exposed by the transport.
 * null headers means metadata is unavailable, whereas {} means no headers were exposed.
 */
export interface SwaggerHttpResponse<T> {
  status: number;
  body: T | null;
  /** True when the transport knows no response body was received. */
  empty?: boolean;
  headers: Readonly<Record<string, readonly string[]>> | null;
  url: string | null;
}

export interface SwaggerRequestOptions {
  headers?: Record<string, string>;
  context?: HttpContext;
  observe?: 'body' | 'response';
}

export interface SwaggerPreparedRequest<T> {
  readonly request: SwaggerHttpRequest;
  send(): Observable<T>;
  sendResponse(): Observable<SwaggerHttpResponse<T>>;
}

/**
 * Defines the HTTP adapter contract used by the generated Angular swagger client.
 */
export interface SwaggerHttpClient {

  /**
   * Executes an HTTP request and returns the typed response stream.
   *
   * @param request The normalized swagger HTTP request.
   * @returns An observable of the full HTTP response.
   */
  request<T>(request: SwaggerHttpRequest): Observable<SwaggerHttpResponse<T>>;
}

/**
 * Resolves the request variable object accepted by a generated endpoint.
 */
export type SwaggerRequestVariables<TEndpoint extends AnyApiEndpoint> =
  OptionalProperty<'pathVariables', PathVariablesOf<TEndpoint>> &
  OptionalProperty<'queryVariables', QueryVariablesOf<TEndpoint>> &
  OptionalProperty<'headerVariables', HeaderVariablesOf<TEndpoint>> &
  OptionalProperty<'bodyVariables', BodyVariablesOf<TEndpoint>>;

type OptionalProperty<TKey extends string, TValue> = IsEmptyVariables<TValue> extends true
  ? { [K in TKey]?: never }
  : undefined extends TValue
    ? { [K in TKey]?: TValue }
    : { [K in TKey]: TValue };

type IsEmptyVariables<TValue> = keyof TValue extends never
  ? true
  : TValue extends Record<string, never>
    ? true
    : false;

export const SWAGGER_CLIENT_CONFIG = new InjectionToken<SwaggerClientConfig>('SWAGGER_CLIENT_CONFIG');
export const SWAGGER_HTTP_CLIENT = new InjectionToken<SwaggerHttpClient>('SWAGGER_HTTP_CLIENT');

/**
 * Adapts Angular HttpClient to the generated swagger HTTP adapter contract.
 */
@Injectable()
export class AngularSwaggerHttpClient implements SwaggerHttpClient {

  /**
   * Creates the default Angular HTTP adapter.
   *
   * @param http The Angular HttpClient used to execute requests.
   */
  constructor(@Inject(HttpClient) private readonly http: HttpClient) {}

  /**
   * Executes a normalized swagger request with Angular HttpClient.
   *
   * @param request The normalized swagger HTTP request.
   * @returns An observable of the full HTTP response.
   */
  request<T>(request: SwaggerHttpRequest): Observable<SwaggerHttpResponse<T>> {
    return this.http.request<T>(request.method, request.url, {
      observe: 'response',
      context: request.context,
      body: request.body,
      headers: new HttpHeaders(request.headers ?? {}),
      params: toHttpParams(request.query)
    }).pipe(map(response => ({
      status: response.status,
      body: request.method === 'HEAD' || response.status === 204 || response.status === 205 ? null : response.body,
      headers: Object.fromEntries(response.headers.keys().map(key => [key.toLowerCase(), response.headers.getAll(key) ?? []])),
      url: response.url
    })));
  }
}

/**
 * Sends typed requests to generated API endpoint definitions.
 */
@Injectable()
export class SwaggerClientService {

  /**
   * Creates the generated swagger client service.
   *
   * @param config The swagger client runtime configuration.
   * @param http The HTTP adapter used to execute requests.
   */
  constructor(
    @Inject(SWAGGER_CLIENT_CONFIG) private readonly config: SwaggerClientConfig,
    @Inject(SWAGGER_HTTP_CLIENT) private readonly http: SwaggerHttpClient
  ) {}

  /**
   * Sends a typed request for a generated API endpoint.
   *
   * @param endpoint The generated endpoint definition to call.
   * @param variables The path, query, header, and body variables for the endpoint.
   * @returns An observable of the endpoint response type; HTTP failures are emitted through its error channel.
   * @throws When a required path variable is missing during request construction.
   */
  request<TEndpoint extends AnyApiEndpoint>(
    endpoint: TEndpoint, variables: SwaggerRequestVariables<TEndpoint> | undefined,
    options: SwaggerRequestOptions & { observe: 'response' }
  ): Observable<SwaggerHttpResponse<ResponseOf<TEndpoint>>>;
  request<TEndpoint extends AnyApiEndpoint>(
    endpoint: TEndpoint, variables?: SwaggerRequestVariables<TEndpoint>,
    options?: SwaggerRequestOptions & { observe?: 'body' }
  ): Observable<ResponseOf<TEndpoint>>;
  request<TEndpoint extends AnyApiEndpoint>(
    endpoint: TEndpoint, variables: SwaggerRequestVariables<TEndpoint> | undefined,
    options: SwaggerRequestOptions
  ): Observable<ResponseOf<TEndpoint> | SwaggerHttpResponse<ResponseOf<TEndpoint>>>;
  request<TEndpoint extends AnyApiEndpoint>(
    endpoint: TEndpoint, variables?: SwaggerRequestVariables<TEndpoint>, options: SwaggerRequestOptions = {}
  ): Observable<ResponseOf<TEndpoint> | SwaggerHttpResponse<ResponseOf<TEndpoint>>> {
    const prepared = this.prepare(endpoint, variables, options);
    return options.observe === 'response' ? prepared.sendResponse() : prepared.send();
  }

  /** Resolves an isolated snapshot without calling the adapter. HttpContext retains its Angular identity. */
  prepare<TEndpoint extends AnyApiEndpoint>(
    endpoint: TEndpoint, variables?: SwaggerRequestVariables<TEndpoint>, options: SwaggerRequestOptions = {}
  ): SwaggerPreparedRequest<ResponseOf<TEndpoint>> {
    const request = snapshot(buildRequest(this.config.baseUrl, endpoint, variables));
    request.headers = mergeHeaders(request.headers, options.headers);
    request.context = options.context;
    const sendResponse = () => defer(() => this.http.request<ResponseOf<TEndpoint>>(snapshot(request))).pipe(
      map(response => {
        if (response.status < 200 || response.status >= 300) throw new SwaggerHttpError(response);
        return request.method === 'HEAD' || response.status === 204 || response.status === 205
          ? { ...response, body: null, empty: true } : response;
      })
    );
    return {
      request: snapshot(request),
      sendResponse,
      // Angular's legacy body mode returns null for empty responses, despite its nonnullable generic.
      send: () => sendResponse().pipe(map(response => response.body as ResponseOf<TEndpoint>))
    };
  }
}

/**
 * Provides the generated Angular swagger client and its HTTP adapter in an environment injector.
 *
 * @param config The swagger client runtime configuration.
 * @returns Environment providers for application or route configuration.
 */
export function provideSwaggerClient(config: SwaggerClientConfig): EnvironmentProviders {
  return makeEnvironmentProviders([
    { provide: SWAGGER_CLIENT_CONFIG, useValue: config },
    { provide: SWAGGER_HTTP_CLIENT, useClass: config.httpClient ?? AngularSwaggerHttpClient },
    SwaggerClientService
  ]);
}

function buildRequest<TEndpoint extends AnyApiEndpoint>(
  baseUrl: string,
  endpoint: TEndpoint,
  variables?: SwaggerRequestVariables<TEndpoint>
): SwaggerHttpRequest {
  const pathVariables = variables?.pathVariables as Record<string, unknown> | undefined;
  const queryVariables = variables?.queryVariables as Record<string, unknown> | undefined;
  const headerVariables = variables?.headerVariables as Record<string, unknown> | undefined;
  const bodyVariables = variables?.bodyVariables;
  const path = endpoint.path.replace(/\{([^}]+)\}/g, (_, key: string) => {
    const value = pathVariables?.[key];

    if (value === undefined || value === null) {
      throw new Error('Missing path variable "' + key + '" for endpoint "' + endpoint.name + '".');
    }

    return encodeURIComponent(String(value));
  });

  return {
    method: endpoint.method,
    url: joinUrl(baseUrl, path),
    headers: stringifyRecord(headerVariables),
    query: queryVariables,
    body: bodyVariables
  };
}

/** A custom adapter returned an unsuccessful response instead of emitting an error. */
export class SwaggerHttpError extends Error {
  constructor(readonly response: SwaggerHttpResponse<unknown>) {
    super('Swagger request failed with status ' + response.status + '.');
  }
}

function snapshot(request: SwaggerHttpRequest): SwaggerHttpRequest {
  return { ...request, headers: request.headers && { ...request.headers },
    query: request.query && structuredClone(request.query),
    body: cloneBody(request.body) };
}

function cloneBody(body: unknown): unknown {
  if (body === undefined || body instanceof HttpParams) return body;
  if (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams) return new URLSearchParams(body);
  if (typeof FormData !== 'undefined' && body instanceof FormData) {
    const copy = new FormData();
    body.forEach((value, key) => copy.append(key, value));
    return copy;
  }
  return structuredClone(body);
}

function mergeHeaders(...records: (Record<string, string> | undefined)[]): Record<string, string> {
  const result: Record<string, string> = {};
  for (const record of records) {
    for (const [key, value] of Object.entries(record ?? {})) result[key.toLowerCase()] = value;
  }
  return result;
}

function toHttpParams(query: Record<string, unknown> | undefined): HttpParams {
  let params = new HttpParams();

  for (const [key, value] of Object.entries(query ?? {})) {
    if (value === undefined || value === null) {
      continue;
    }

    if (Array.isArray(value)) {
      for (const item of value) {
        params = params.append(key, String(item));
      }
    } else {
      params = params.set(key, String(value));
    }
  }

  return params;
}

function stringifyRecord(record: Record<string, unknown> | undefined): Record<string, string> | undefined {
  if (!record) {
    return undefined;
  }

  return Object.fromEntries(
    Object.entries(record)
      .filter(([, value]) => value !== undefined && value !== null)
      .map(([key, value]) => [key, String(value)])
  );
}

function joinUrl(baseUrl: string, path: string): string {
  if (/^https?:\/\//i.test(path)) {
    return path;
  }

  return baseUrl.replace(/\/+$/, '') + '/' + path.replace(/^\/+/, '');
}
`;
}
